import{c as a,Q as e,j as i,m as l}from"./chunks/framework.D55kK6e8.js";const p=JSON.parse('{"title":"用户认证","description":"","frontmatter":{},"headers":[],"relativePath":"guide/authentication.md","filePath":"guide/authentication.md"}'),o={name:"guide/authentication.md"};function r(d,t,n,h,c,s){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="用户认证" tabindex="-1">用户认证 <a class="header-anchor" href="#用户认证" aria-label="Permalink to &quot;用户认证&quot;">​</a></h1><p>系统支持两种访问模式：标准登录模式和看板免登录模式。</p><h2 id="标准模式" tabindex="-1">标准模式 <a class="header-anchor" href="#标准模式" aria-label="Permalink to &quot;标准模式&quot;">​</a></h2><h3 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h3><p>访问 <code>/login</code> 页面，输入账号密码登录。登录成功后：</p><ul><li>Token 存储在 localStorage</li><li>自动跳转到之前访问的页面</li><li>未登录用户访问需要认证的页面会被重定向到登录页</li></ul><h3 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to &quot;注册&quot;">​</a></h3><p>新用户可以通过注册页面创建账号，需要填写：</p><ul><li>用户名</li><li>密码</li><li>真实姓名</li><li>角色（医生、护士、医技人员、行政人员、其他）</li><li>科室</li><li>联系电话（可选）</li><li>邮箱（可选）</li></ul><h3 id="用户信息" tabindex="-1">用户信息 <a class="header-anchor" href="#用户信息" aria-label="Permalink to &quot;用户信息&quot;">​</a></h3><p>登录后，顶部导航栏显示用户信息：</p><ul><li>头像（姓名首字母）</li><li>姓名和角色</li><li>所属科室</li><li>退出登录按钮</li></ul><h2 id="看板模式" tabindex="-1">看板模式 <a class="header-anchor" href="#看板模式" aria-label="Permalink to &quot;看板模式&quot;">​</a></h2><p>看板模式适用于公共展示场景，无需手动登录：</p><ol><li>在 <code>src/support/config.ts</code> 中配置账号密码</li><li>设置 <code>enabled: true</code></li><li>系统启动时自动使用配置账号登录</li><li>直接跳转到看板首页</li></ol><div class="warning custom-block"><p class="custom-block-title">安全提示</p><p>看板模式会将凭据存储在前端代码中，仅适用于受信任的内部网络环境。</p></div><h2 id="权限角色" tabindex="-1">权限角色 <a class="header-anchor" href="#权限角色" aria-label="Permalink to &quot;权限角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>权限</th></tr></thead><tbody><tr><td>管理员</td><td>所有操作权限</td></tr><tr><td>医生</td><td>创建工单、查看工单、编辑自己创建的工单</td></tr><tr><td>护士</td><td>创建工单、查看工单、编辑自己创建的工单</td></tr><tr><td>其他</td><td>创建工单、查看工单、编辑自己创建的工单</td></tr></tbody></table>',18)])])}const b=a(o,[["render",r]]);export{p as __pageData,b as default};
